const rows = $input.all().map(i => i.json);
const sources = [];
for (const row of rows) {
  if (Array.isArray(row.items)) {
    for (const x of row.items.slice(0, 8)) sources.push({type:'GitHub', title:x.full_name, description:x.description || '', url:x.html_url, score:x.stargazers_count || 0});
  }
  if (Array.isArray(row.hits)) {
    for (const x of row.hits.slice(0, 12)) sources.push({type:'News', title:x.title || x.story_title || '', description:'', url:x.url || x.story_url || ('https://news.ycombinator.com/item?id=' + x.objectID), score:x.points || 0});
  }
}
const sourceText = sources.map((x,i) => `${i+1}. [${x.type}] ${x.title} | 관심도 ${x.score} | ${x.description} | ${x.url}`).join('\n');
return [{json:{source_count:sources.length, sources, source_text:sourceText, report_date:new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date())}}];
